function ex(title:Bilingual,skills:MathSkill[],prompt:Bilingual,hints:Bilingual[],solution:Bilingual[],rubric:Bilingual[],commonErrors:Bilingual[],remediation:number[],critical?:boolean[]):SeedExercise { return {title,skills,prompt,hints,solution,rubric,commonErrors,remediation,critical}; }
function plan(topic:Bilingual,focuses:Bilingual[]):[Bilingual,Bilingual,Bilingual,Bilingual][] { return focuses.map((f,i)=>[
 b('Study '+topic.en+' and reconstruct the hypotheses needed for: '+f.en,'Ôn '+topic.vi+' và dựng lại giả thiết cần cho: '+f.vi),
 b('Spend the independent block solving this specific task: '+f.en,'Dùng khối tự giải để làm nhiệm vụ cụ thể: '+f.vi),
 b('Check the derivation against the defining identity and test the stated boundary case: '+f.en,'Đối chiếu suy diễn với đồng nhất thức định nghĩa và kiểm tra trường hợp biên: '+f.vi),
 b('Close notes; write the conclusion and one invalid shortcut for: '+f.en,'Đóng ghi chú; viết kết luận và một lối tắt sai cho: '+f.vi),
] as [Bilingual,Bilingual,Bilingual,Bilingual]); }
function makeExercise(week:number,index:number,x:SeedExercise):MathExercise {
 const {critical,...content}=x;
 return {
  id:'m2-w'+String(week).padStart(3,'0')+'-e'+index,revision:1,...content,
  rubric:x.rubric.map((criterion,i)=>({points:2,criterion,...(critical?.[i]?{critical:true}:{})})),
 };
}
function makeWeek(x:Seed):MathWeek {
 const exercises=[...x.exercises,...(x.alternates??[])].map((e,i)=>makeExercise(x.week,i+1,e));
 const wid='m2-w'+String(x.week).padStart(3,'0');
 return {
  week:x.week,revision:1,title:x.title,level:'graduate core',prerequisites:x.prerequisites,outcomes:x.outcomes,definitions:x.definitions,
  theorems:[{id:wid+'-t1',...x.theorem}],workedExample:x.workedExample,failureCase:x.failureCase,exercises,
  sessions:x.actions.map((actions,day)=>({
   title:x.sessionTitles?.[day]??x.deliverables[day],
   exerciseIds:[exercises[day].id],theoremIds:[wid+'-t1'],actions,deliverable:x.deliverables[day],
   mode:x.assessment?'assessment':'study',
   ...(x.alternates?.length?{alternativeExerciseIds:[exercises[day+x.exercises.length].id]}:{}),
  })),
  reading:[{sourceId:x.readingSource,section:x.readingSection,purpose:x.readingPurpose,required:true}],
  errorChecklist:x.errors,coverage:x.coverage,
 };
}

